'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );
var EPS = require( '@stdlib/constants/float32/eps' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );


// FIXTURES //

var mediumNegative = require( './fixtures/python/medium_negative.json' );
var mediumPositive = require( './fixtures/python/medium_positive.json' );
var smallNegative = require( './fixtures/python/small_negative.json' );
var smallPositive = require( './fixtures/python/small_positive.json' );
var tiny = require( './fixtures/python/tiny.json' );


// VARIABLES //

var expm1relf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( expm1relf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof expm1relf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function accurately computes `(exp(x)-1)/x` for negative medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expm1relf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `(exp(x)-1)/x` for positive medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	// NOTE: the tolerance here is larger due to error amplification in the branch for `x >= max(ln(FLT_MAX))`, where the function computes `(expm1(x/2)/x) * (expm1(x/2)+2)`.
	for ( i = 0; i < x.length; i++ ) {
		v = expm1relf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `(exp(x)-1)/x` for negative small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = smallNegative.x;
	expected = smallNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expm1relf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `(exp(x)-1)/x` for positive small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = smallPositive.x;
	expected = smallPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expm1relf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `(exp(x)-1)/x` for very small `x`', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = tiny.x;
	expected = tiny.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expm1relf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `1.0` near `0.0`', opts, function test( t ) {
	t.strictEqual( expm1relf( 0 ), 1.0, 'equals 1.0' );
	t.strictEqual( expm1relf( EPS ), 1.0, 'equals 1.0' );
	t.strictEqual( expm1relf( -EPS ), 1.0, 'equals 1.0' );
	t.end();
});

tape( 'the function returns `NaN` when evaluated at `NaN`', opts, function test( t ) {
	var y = expm1relf( NaN );
	t.strictEqual( isnanf( y ), true, 'equals NaN' );
	t.end();
});

tape('the function returns `+infinity` at `+infinity`', opts, function test( t ) {
	t.strictEqual( expm1relf( PINF ), PINF, 'equals +infinity' );
	t.end();
});

tape('the function returns a finite value at the last input which does not overflow', opts, function test( t ) {
	var v = expm1relf( 93.25820922851562 );
	t.notEqual( v, PINF, 'does not overflow' );
	t.ok( isAlmostSameValuef( v, f32( 3.402816957389172e38 ), 2 ), 'within 2 ULP of the float64 reference' );
	t.end();
});

tape('the function returns `+infinity` at the first input which overflows', opts, function test( t ) {
	t.strictEqual( expm1relf( 93.25821685791016 ), PINF, 'equals +infinity' );
	t.end();
});

tape('the function returns `0` at `-infinity`', opts, function test( t ) {
	t.strictEqual( expm1relf( NINF ), 0.0, 'equals 0' );
	t.end();
});
